package com.bank.feed;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FeedParserDemo {
    private static final Logger log = Logger.getLogger(FeedParserDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        log.info(() -> "Parsing feed for " + rajesh.getAccountId());

        FeedParserService svc = new FeedParserService();

        // Gotcha 1: trailing empty fields (blank memo + blank channel).
        String line = "TXN-1,SAV2001,45000.00,,";
        log.warning(() -> "default split count = "
                + line.split(",").length + " (drops trailing empties!)");
        TxnRecord rec = svc.parseRecord(line);
        log.info(() -> "parsed record = " + rec);

        // Gotcha 2: the argument is a REGEX; split on a literal dot.
        String[] badDot = "2.1.0".split(".");    // matches ANYTHING → empty array
        log.warning(() -> "unescaped dot split length = " + badDot.length + " (WRONG)");
        List<String> version = svc.splitVersion("2.1.0");
        log.info(() -> "escaped dot split = " + version);

        // Gotcha 3: splitting an empty string returns ["" ] (length 1).
        List<String> empties = svc.tokenizeLine("");
        log.info(() -> "tokenize empty line -> tokens = " + empties.size());
    }
}

