class TxnRecord {
    private final String txnId;
    private final String accountId;
    private final BigDecimal amount;
    private final String memo;
    private final String channel;

    TxnRecord(String txnId, String accountId, BigDecimal amount, String memo, String channel) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.memo = memo;
        this.channel = channel;
    }
    @Override public String toString() {
        return "TxnRecord{id=" + txnId + ", acct=" + accountId + ", amt=" + amount
                + ", memo='" + memo + "', channel='" + channel + "'}";
    }
}

// ─── Would be in service/FeedParserService.java in a real project ───
class FeedParserService {
    private static final Logger log = Logger.getLogger(FeedParserService.class.getName());

    // Negative limit KEEPS trailing empty fields so columns stay aligned.
    TxnRecord parseRecord(String line) {
        String[] f = line.split(",", -1);   // keep empties
        if (f.length < 5) {
            throw new IllegalArgumentException("Expected 5 fields, got " + f.length);
        }
        return new TxnRecord(f[0], f[1], new BigDecimal(f[2]),
                f[3], f[4]);                 // f[3]/f[4] may legitimately be empty
    }

    // Escape the dot so it is a LITERAL, not "any character".
    List<String> splitVersion(String version) {
        return List.of(version.split("\\."));   // \\. matches a literal dot
        // Alternative: version.split(java.util.regex.Pattern.quote("."))
    }

    // Guard empty input: split("") returns [""] (length 1), not empty.
    List<String> tokenizeLine(String line) {
        if (line == null || line.isEmpty()) {
            log.warning("Empty line — returning zero tokens (guarded).");
            return List.of();
        }
        return List.of(line.split(",", -1));
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
